import{_ as a,o as t,c as o,a2 as n}from"./chunks/framework.D7WGirly.js";const u=JSON.parse('{"title":"Roadmaps — How-tos & Workflows","description":"","frontmatter":{},"headers":[],"relativePath":"roadmaps-02-how-tos-and-workflows.md","filePath":"roadmaps-02-how-tos-and-workflows.md"}'),r={name:"roadmaps-02-how-tos-and-workflows.md"};function i(l,e,s,d,h,p){return t(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="roadmaps-—-how-tos-workflows" tabindex="-1">Roadmaps — How-tos &amp; Workflows <a class="header-anchor" href="#roadmaps-—-how-tos-workflows" aria-label="Permalink to &quot;Roadmaps — How-tos &amp; Workflows&quot;">​</a></h1><p><em>Step-by-step guides for the most common Roadmap workflows</em></p><hr><h2 id="creating-a-roadmap" tabindex="-1">Creating a Roadmap <a class="header-anchor" href="#creating-a-roadmap" aria-label="Permalink to &quot;Creating a Roadmap&quot;">​</a></h2><ol><li>Navigate to the Roadmaps module from the left-hand navigation.</li><li>Create a new Roadmap and give it a name. Names can be changed at any time.</li><li>Begin adding items using the bulleted list entry field.</li></ol><p>As you add items, they immediately appear in the sunburst visualization on the right. There&#39;s no separate &quot;preview&quot; step — the sunburst is live.</p><hr><h2 id="adding-items-to-a-roadmap" tabindex="-1">Adding Items to a Roadmap <a class="header-anchor" href="#adding-items-to-a-roadmap" aria-label="Permalink to &quot;Adding Items to a Roadmap&quot;">​</a></h2><p>The item entry field works in two ways:</p><ul><li><strong>Type a new item</strong> — creates a new entry and simultaneously adds it to your Feature backlog</li><li><strong>Select an existing Feature</strong> — the entry field doubles as a dropdown showing Features from your backlog; selecting one links it to the Roadmap without creating a duplicate</li></ul><blockquote><p><strong>Tip:</strong> You don&#39;t need to set up your backlog before building a Roadmap. You can type new items directly into the Roadmap and they&#39;ll be added to your backlog automatically.</p></blockquote><hr><h2 id="building-hierarchy-with-drag-and-drop" tabindex="-1">Building Hierarchy with Drag and Drop <a class="header-anchor" href="#building-hierarchy-with-drag-and-drop" aria-label="Permalink to &quot;Building Hierarchy with Drag and Drop&quot;">​</a></h2><p>Hierarchy is the heart of a Lodestone Roadmap. It&#39;s created entirely through drag and drop.</p><ol><li>Add your items to the list.</li><li>Drag an item beneath another item to make it a child.</li><li>Continue nesting to create as many levels as you need — there is no limit.</li><li>To reorder items within the same level, drag them up or down relative to their siblings.</li></ol><p>The sunburst updates in real time as you nest and reorder, so you can see the structure forming as you work.</p><blockquote><p><strong>Note:</strong> Drag-and-drop nesting is not immediately obvious the first time. If your sunburst looks flat (everything in one ring), check whether your items need to be nested beneath a parent item.</p></blockquote><hr><h2 id="understanding-dynamic-object-behavior" tabindex="-1">Understanding Dynamic Object Behavior <a class="header-anchor" href="#understanding-dynamic-object-behavior" aria-label="Permalink to &quot;Understanding Dynamic Object Behavior&quot;">​</a></h2><p>When you nest an item beneath another, something important happens:</p><ul><li>The <strong>parent item</strong> disappears from the Feature backlog</li><li>It becomes a <strong>tag</strong> applied to all its children</li><li>All child Features inherit their parent (and grandparent) items as tags</li></ul><p>This means your backlog stays focused on actionable Features, while the hierarchy context is preserved through tags. If you want a grouping label (like a Goal or Theme) that doesn&#39;t clutter your backlog, simply nest Features beneath it.</p><hr><h2 id="setting-colors" tabindex="-1">Setting Colors <a class="header-anchor" href="#setting-colors" aria-label="Permalink to &quot;Setting Colors&quot;">​</a></h2><p>Each item in the Roadmap has a colored bullet. To set or change a color:</p><ol><li>Click the colored bullet next to an item.</li><li>Choose a color from the picker.</li></ol><p>Colors propagate from parent items to their children automatically. Setting a color on a parent applies it to the whole group in the sunburst.</p><hr><h2 id="activating-contextual-sizing-and-coloring" tabindex="-1">Activating Contextual Sizing and Coloring <a class="header-anchor" href="#activating-contextual-sizing-and-coloring" aria-label="Permalink to &quot;Activating Contextual Sizing and Coloring&quot;">​</a></h2><p>To add Value or Effort context to the outermost ring of the sunburst:</p><ol><li>Ensure your Features have Value and Effort scores entered in the Feature backlog — these controls are only active when scores exist.</li><li>Locate the <strong>Size By</strong> dropdown and <strong>Color By Context</strong> toggle above the sunburst.</li><li>Use <strong>Size By</strong> to resize Feature segments by Value/Impact or Effort.</li><li>Toggle <strong>Color By Context</strong> to color Feature segments by Value/Impact or Effort, using a customizable scale.</li></ol><p>You can activate both at the same time — for example, sizing by Value and coloring by Effort — to show leverage (large, green = high value, low effort) at a glance.</p><blockquote><p><strong>Note:</strong> Contextual sizing and coloring only affect the outermost ring. Parent and grandparent color families remain intact.</p></blockquote><hr><h2 id="renaming-a-roadmap" tabindex="-1">Renaming a Roadmap <a class="header-anchor" href="#renaming-a-roadmap" aria-label="Permalink to &quot;Renaming a Roadmap&quot;">​</a></h2><p>Roadmap names can be changed at any time. Click the Roadmap name to edit it directly.</p><hr><h2 id="archiving-a-roadmap" tabindex="-1">Archiving a Roadmap <a class="header-anchor" href="#archiving-a-roadmap" aria-label="Permalink to &quot;Archiving a Roadmap&quot;">​</a></h2><p>When a Roadmap is no longer active:</p><ol><li>Open the Roadmap settings or options menu.</li><li>Select Archive.</li></ol><p>Archiving removes the Roadmap from your active list but preserves it for reference. All Features that were in the Roadmap remain in your backlog — archiving has no effect on them.</p><hr><h2 id="exporting-a-roadmap" tabindex="-1">Exporting a Roadmap <a class="header-anchor" href="#exporting-a-roadmap" aria-label="Permalink to &quot;Exporting a Roadmap&quot;">​</a></h2><p>Roadmaps can be exported in four formats:</p><h3 id="png-—-single-view" tabindex="-1">PNG — single view <a class="header-anchor" href="#png-—-single-view" aria-label="Permalink to &quot;PNG — single view&quot;">​</a></h3><p>A static image of the full sunburst. Useful for dropping into emails, documents, or slides you&#39;re assembling manually.</p><h3 id="ppt-—-single-view" tabindex="-1">PPT — single view <a class="header-anchor" href="#ppt-—-single-view" aria-label="Permalink to &quot;PPT — single view&quot;">​</a></h3><p>A single PowerPoint slide containing the sunburst. Useful when you want to include the roadmap visualization in an existing presentation.</p><h3 id="ppt-—-full-presentation" tabindex="-1">PPT — full presentation <a class="header-anchor" href="#ppt-—-full-presentation" aria-label="Permalink to &quot;PPT — full presentation&quot;">​</a></h3><p>A complete PowerPoint deck that walks through the entire plan. Lodestone generates a slide for every item at every level of the hierarchy, deconstructing the sunburst step by step. Opportunity Canvases for Features in the Roadmap are collected automatically and appended as an appendix.</p><h3 id="markdown-md" tabindex="-1">Markdown (.md) <a class="header-anchor" href="#markdown-md" aria-label="Permalink to &quot;Markdown (.md)&quot;">​</a></h3><p>A text-based export of the full Roadmap hierarchy, formatted as a Markdown document. Useful for pasting into Notion, Confluence, GitHub, or any other tool that accepts Markdown. The export reflects the current hierarchy exactly as structured in Lodestone.</p><h3 id="html-shareable-link" tabindex="-1">HTML (shareable link) <a class="header-anchor" href="#html-shareable-link" aria-label="Permalink to &quot;HTML (shareable link)&quot;">​</a></h3><p>Generates a responsive, server-rendered HTML snapshot of your Roadmap and returns a shareable link. Unlike the other export formats, this does not download a file — it produces a <code>/share/...</code> URL you can copy and send to anyone. The recipient can view the Roadmap in a browser without logging in to Lodestone.</p><p>To generate an HTML export, click the <strong>Export as HTML</strong> button in the Roadmap toolbar. Once generated, the link is displayed alongside a <strong>Copy Link</strong> button. You can regenerate a new snapshot at any time — each generation produces a new URL.</p><hr><h2 id="adding-ai-generated-content-to-exports" tabindex="-1">Adding AI-Generated Content to Exports <a class="header-anchor" href="#adding-ai-generated-content-to-exports" aria-label="Permalink to &quot;Adding AI-Generated Content to Exports&quot;">​</a></h2><p>When exporting as a full PPT presentation, you can optionally enable AI-generated content:</p><ul><li><strong>Text box descriptions</strong> — a short description generated per slide, explaining what is shown</li><li><strong>Speaker notes</strong> — optional notes tuned for your chosen audience: <ul><li>Internal general staff</li><li>Internal executive</li><li>External</li></ul></li></ul><p>To enable these, select the relevant options in the export settings before generating the PPT. All AI-generated content is clearly marked and fully editable in PowerPoint after export.</p><hr><p><em>Next: Advanced Features &amp; Customization — contextual visualization, hierarchy strategy, and presentation tips.</em></p>',62)])])}const g=a(r,[["render",i]]);export{u as __pageData,g as default};
